  "jxg.preview_lbl":        "Vorschau (JSXGraph-Rendering des eingefügten Codes):",
  "jxg.preview_first":      "Fügen Sie zuerst Code zur Vorschau ein.",

  "jxg.prompt_intro":       "Du erzeugst eine KLASSISCHE, EIGENSTÄNDIGE JSXGraph-Grafik (allein in einem\nBrowser testbar). Kümmere dich NICHT um STACK/Moodle: Ich wandle deinen\nCode danach selbst um (Syntax [[jsxgraph]], divid, {#…#}) — du musst sie nicht kennen.",
  "jxg.prompt_rules_header":"━━ REGELN ━━",
  "jxg.prompt_rule1":       "1. Vollständige, eigenständige Struktur:\n   <div id=\"box\" style=\"width:{w};height:{h};\"></div>\n   <script src=\"https://cdn.jsdelivr.net/npm/jsxgraph/distrib/jsxgraphcore.js\"></script>\n   <script>\n   var board = JXG.JSXGraph.initBoard('box', {…});\n   … dein Code …\n   </script>",
  "jxg.prompt_rule2":       "2. Nenne die Board-Variable EXAKT \"board\" und den Container EXAKT\n   \"box\" (wie im Skelett unten).",
  "jxg.prompt_rule3":       "3. Wenn du eine der unten aufgeführten Variablen verwendest, deklariere sie mit\n   einem Beispielwert UND dem Kommentar // POOLVAR: Name in DERSELBEN Zeile\n   (z. B. var a = 3; // POOLVAR: a) — so kann ich sie nach der Konvertierung\n   automatisch verknüpfen.",
  "jxg.prompt_rule4":       "4. Umschließe die Zeichnung mit board.suspendUpdate() / board.unsuspendUpdate().",
  "jxg.prompt_rule5_interactive": "5. Diese Grafik ist INTERAKTIV: Die Punkte, die der Schüler verschieben können\n   muss, sind normale, verschiebbare JSXGraph-Punkte (NICHT fixed:true). Füge\n   direkt nach der Zeile board.create('point', …) JEDES interaktiven Punktes\n   einen Kommentar // BIND: Variablenname (z. B. // BIND: ans1) hinzu, der\n   angibt, welcher STACK-Antwortvariable er entspricht — die Verknüpfung\n   stack_jxg.bind_point mache ich selbst nach der Konvertierung.",
  "jxg.prompt_rule5_display":     "5. Diese Grafik ist NUR ANZEIGE (nicht interaktiv): Alle JSXGraph-Objekte\n   MÜSSEN {fixed:true, highlight:false, visible:true} haben\n   (alle drei — STACK benötigt zusätzlich zu fixed:true auch visible:true).",
  "jxg.prompt_config_header":"━━ KONFIGURATION DES KOORDINATENSYSTEMS (genau einhalten) ━━",
  "jxg.prompt_window":      "Fenster: x von {xmin} bis {xmax}, y von {ymin} bis {ymax}",
  "jxg.prompt_options":     "Optionen: {opts}",
  "jxg.prompt_vars_header": "━━ VERFÜGBARE VARIABLEN ━━",
  "jxg.prompt_var_line":    "  {n}  →  var {n} = <Beispielwert>; // POOLVAR: {n}",
  "jxg.prompt_no_vars":     "(keine Variable im Pool für dieses Quiz definiert)",
  "jxg.prompt_skeleton_header": "━━ REFERENZ-SKELETT (genau diese Konfiguration für initBoard verwenden) ━━",
  "jxg.prompt_request_header":  "━━ ANFRAGE ━━",
  "jxg.prompt_no_desc":     "(keine Beschreibung angegeben)",
  "jxg.prompt_draw_here":   "/* --- Zeichnung hier --- */",
  "jxg.prompt_reticule_comment": "/* --- Fadenkreuz: gekreuzte Linien + Koordinaten beim Überfahren --- */",
  "jxg.prompt_footer":      "Antworte NUR mit dem Code (div + script), bereit zum Einfügen und Testen in\neinem Browser, eingeschlossen in einen Markdown-Codeblock (```html am Anfang, ```\nam Ende) — sonst führen manche Chat-Oberflächen das HTML/JS aus,\nstatt es als Text anzuzeigen. Keine Erklärung davor oder danach.",
  "jxg.opt_axes_on":        "Achsen sichtbar",
  "jxg.opt_axes_off":       "keine Achsen",
  "jxg.opt_grid_on":        "Gitter",
  "jxg.opt_grid_off":       "kein Gitter",
