  "match.prompt_bullet_left":    "Die linke Spalte (leftItems) enthält Konzepte, konkrete Beispiele, Werte oder Fallbeispiele.",
  "match.prompt_bullet_right":   "Die rechte Spalte (rightItems) enthält allgemeine Kategorien, Definitionen, Eigenschaften oder Schwellenwerte.",
  "match.prompt_bullet_constraint": "VERPFLICHTENDE DIDAKTISCHE VORGABE (KEINE 1-ZU-1-ZUORDNUNG): Die Aufgabe darf KEINE einfache lineare Zuordnung sein. Gestalte sie so, dass ein Element rechts mit mehreren Elementen links verknüpft ist (Viele-zu-Eins), oder ein Element links mit mehreren Eigenschaften rechts verbunden ist (Viele-zu-Viele).",
  "match.prompt_bullet_lang":    "Die zu verwendende Sprache ist {lang}.",
  "match.prompt_tech_title":     "### STRIKTE TECHNISCHE VORGABEN",
  "match.prompt_tech1":          "1. AUSGABEFORMAT: Ausschließlich reines JSON (kein Fließtext, keine Markdown-Codeblöcke, nur das JSON-Objekt).",
  "match.prompt_tech2":          "2. STRUKTUR DER ELEMENTE: Jedes Objekt in „leftItems“ und „rightItems“ muss exakt diese Struktur haben:",
  "match.prompt_tech3":          "3. STRUKTUR DER VERBINDUNGEN: Das Array „connections“ muss ein Array von numerischen Indexpaaren sein (beginnend bei 0). Beispiel: [[0, 0], [1, 2], [2, 2]]. Keine Objekte mit den Schlüsseln leftId/rightId verwenden.",
  "match.prompt_tech4":          "4. ASYMMETRIE: Die Anzahl der Elemente links und rechts muss unterschiedlich sein. Ein rechter Index MUSS mehrfach im Array „connections“ vorkommen, um die nichtlineare Struktur zu bestätigen.",
  "match.prompt_tech5":          "5. JSON-ESCAPING: Innerhalb von Zeichenketten jeden Backslash verdoppeln (\\\\) und interne Anführungszeichen escapen (\\\"). Anführungszeichen in HTML-Attributen korrekt escapen. Das JSON muss unverändert gültig sein.",
  "match.prompt_example_title":  "### BEISPIEL FÜR DIE ERWARTETE STRUKTUR (asymmetrisches Viele-zu-Eins-Modell)",
  "match.prompt_example_left1":  "Hund",
  "match.prompt_example_left2":  "Adler",
  "match.prompt_example_left3":  "Katze",
  "match.prompt_example_right1": "Säugetiere",
  "match.prompt_example_right2": "Vögel",
  "match.prompt_final_title":    "### ABSCHLIESSENDE KONTROLLE (vor der Antwort)",
  "match.prompt_final_check":    "Prüfe, dass: (1) das JSON syntaktisch gültig ist; (2) alle Backslashes verdoppelt und interne Anführungszeichen escaped sind; (3) die Struktur (id/html/text, connections als Indexpaare) eingehalten wird; (4) Asymmetrie vorhanden ist; (5) kein Text außerhalb des JSON-Blocks steht. Falls du diese Vorgaben nicht einhalten kannst, gib ein leeres JSON-Objekt {} zurück.",
  "match.prompt_task_title":     "### AUFGABE",
  "match.prompt_task":           "Erzeuge jetzt das finale JSON für das Thema: {subject}",

