  "cw.prompt_role":       "Du bist ein erfahrener Kreuzworträtsel-Ersteller und ein pädagogischer Lehrer für {ctx}. Erstelle eine Liste von Wörtern und ihren Definitionen, um ein Kreuzworträtsel-Gitter zu erstellen.",
  "cw.prompt_theme_lbl":  "Gewünschtes Thema: {theme}",
