  "cw.prompt_lang_lbl":   "Sprache: {lang}",
  "cw.prompt_rules_lbl":  "Strikte Regeln für die Verknüpfung:",
  "cw.prompt_rule2":      "2. KREUZPRÜFUNG: Stelle vor dem Auflisten eines Wortes sicher, dass es MINDESTENS einen Buchstaben mit mindestens 2 anderen Wörtern deiner Liste teilt.",
  "cw.prompt_rule3":      "3. Die Wörter müssen zwischen 4 und 10 Buchstaben enthalten. Vermeide 2- oder 3-Buchstaben-Wörter, die das Gitter blockieren.",
  "cw.prompt_rule4":      "4. Die Definitionen müssen kurz, klar und im typischen Kreuzworträtsel-Stil sein.",
  "cw.prompt_rule5":      "5. Schreibe die Wörter im Feld \"word\" in GROSSBUCHSTABEN ohne Akzente (z. B. \"SCHULE\" statt \"Schule\"). In den Definitionen kannst du Akzente verwenden.",
  "cw.prompt_rule6":      "6. ABSOLUTES VERBOT: Die Definition darf NIEMALS das gesuchte Wort enthalten, noch ein Wort derselben Wortfamilie (gleicher Wortstamm). Zum Beispiel darf die Definition für das Wort \"REAKTION\" weder \"Reaktion\" noch \"reagieren\" noch \"reaktiv\" enthalten.",
  "cw.prompt_rule7":      "7. ART DER WÖRTER: jedes Wort muss ein SUBSTANTIV im SINGULAR sein. Keine Eigennamen, keine Pluralformen, keine konjugierten Verben, keine zusammengesetzten Wörter (weder Leerzeichen noch Bindestrich).",
  "cw.prompt_json_instr": "Erstelle NUR ein gültiges JSON-Array, ohne zusätzlichen Text davor oder danach, mit genau dieser Struktur:",
  "cw.prompt_json_word_ph": "WORT",
  "cw.prompt_json_def_ph":  "Definition des Wortes hier",
  "cw.prompt_final_check": "ABSCHLUSSPRÜFUNG (vor der Antwort zu prüfen):",
  "cw.prompt_check1":     "- Das JSON-Array ist syntaktisch gültig (korrekte Kommas, Anführungszeichen, Klammern).",
  "cw.prompt_check2":     "- Jeder Backslash ist verdoppelt (\\\\) und jedes interne Anführungszeichen ist escaped (\\\"), um gültiges JSON zu bleiben.",
  "cw.prompt_check3":     "- Keine Definition enthält ihr eigenes Wort (Regel 6); alle Wörter sind Substantive im Singular (Regel 7).",
  "cw.prompt_check4":     "- Kein Text, Kommentar oder Markdown-Tag außerhalb des Arrays.",
