  "ineq.fb_bounds_ok_inclusion_wrong": "Die Grenzen sind richtig, aber prüfe, ob sie eingeschlossen (geschlossene Klammer [ ]) oder ausgeschlossen (offene Klammer ] [) sein sollten. Antwort: {@{tavar}@}.",
