  "lim.title":             "Funktionsgrenzen",
  "lim.node_limite_correcte": "Grenzwert korrekt?",
  "lim.mode_aleatoire":    "Zufällig",
  "lim.mode_fixe":         "Fest (f(x), Punkt und Antwort siehe unten)",
  "lim.scenario_lbl":      "Limitart",
  "lim.scenario_plus_inf": "lim x → +∞",
  "lim.scenario_moins_inf":"lim x → −∞",
