  "lim.tans_examples_html":"Beispiele: <code>3</code>, <code>0</code>, <code>inf</code>, <code>-inf</code>, <code>%pi</code>, <code>1/2</code>",
  "lim.fbgen_auto_desc":   "Die Korrektur (Formel, Wert) wird automatisch entsprechend den in „Konfiguration“ gewählten Einstellungen generiert.",
  "lim.banniere":          "Grenzen",
  "lim.calc_limite":       "Den Grenzwert berechnen:",
  "lim.taper_inf_ou_moins_inf": "Geben Sie <code>inf</code> für \\(+\\infty\\) oder <code>-inf</code> für \\(-\\infty\\) ein.",
  "lim.taper_inf":         "Geben Sie <code>inf</code> für \\(+\\infty\\) ein.",
  "lim.taper_moins_inf":   "Geben Sie <code>-inf</code> für \\(-\\infty\\) ein.",
  "lim.calc_limite_indetermination": "Berechnen (unter Beseitigung der Unbestimmtheit):",
  "lim.calc_limite_droite": "Den Grenzwert rechts berechnen:",
  "lim.calc_limite_gauche": "Den Grenzwert links berechnen:",
  "lim.fb_wrong_fixe":     "<strong>Vorgehensweise</strong>: Versuchen Sie zunächst die direkte Substitution. Wenn dabei eine unbestimmte Form (0/0, ∞/∞, ∞−∞...) entsteht, faktorisieren oder vereinfachen Sie den Ausdruck, bevor Sie den Grenzwert erneut berechnen.<br>Erwartete Antwort: {@{tavar}@}.",
  "lim.fbgen_fixe":        "Der gesuchte Grenzwert ist {@{tavar}@}. Überprüfe die direkte Substitution und, falls die Ausdrucksform unbestimmt ist, faktoriere bzw. vereinfache den Ausdruck, bevor du eine Schlussfolgerung ziehst.",
  "lim.fb_wrong_plus_inf": "<strong>Verfahren</strong>: Bei einem Grenzwert gegen \\(+\\infty\\) eines Polynomquotienten vergleicht man die Grade des Zählers und des Nenners (was dem Herausziehen der dominanten Potenz auf beiden Seiten entspricht).<br>Hier hat der Zähler \\({@{numvar}@}\\) den Grad {@{degnvar}@} (dominanter Koeffizient {@{lcnvar}@}), und der Nenner \\({@{denvar}@}\\) hat den Grad {@{degdvar}@} (dominanter Koeffizient {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; Grenzwert 0.<br>• deg(num) = deg(den) &rarr; Grenzwert = Verhältnis der dominanten Koeffizienten.<br>• deg(num) &gt; deg(den) &rarr; Grenzwert 0.<br>Schlussfolgerung: Der Grenzwert beträgt {@{tavar}@}.",
  "lim.fbgen_plus_inf":    "\\(\\displaystyle\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\) : Zähler vom Grad {@{degnvar}@} (dominanter Koeffizient {@{lcnvar}@}), Nenner vom Grad {@{degdvar}@} (dominanter Koeffizient {@{lcdvar}@}).<br>\\(\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_moins_inf":"<strong>Verfahren</strong>: Bei einem Grenzwert gegen \\(-\\infty\\) eines Polynomquotienten vergleicht man die Grade des Zählers und des Nenners.<br>Hier hat der Zähler \\({@{numvar}@}\\) den Grad {@{degnvar}@} (dominanter Koeffizient {@{lcnvar}@}), und der Nenner \\({@{denvar}@}\\) hat den Grad {@{degdvar}@} (dominanter Koeffizient {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; Grenzwert 0.<br>• deg(num) = deg(den) &rarr; Grenzwert = Verhältnis der dominanten Koeffizienten.<br>• deg(num) &gt; deg(den) &rarr; Grenzwert 0.<br>• deg(num) = deg(den) &rarr; Grenzwert = Verhältnis der dominanten Koeffizienten. <br>Fazit: Der Grenzwert beträgt {@{tavar}@}.",
  "lim.fbgen_moins_inf":   "\\(\\displaystyle\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\) : Zähler vom Grad {@{degnvar}@} (dominanter Koeffizient {@{lcnvar}@}), Nenner vom Grad {@{degdvar}@} (dominanter Koeffizient {@{lcdvar}@}).<br>\\(\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_point_fini":"<strong>Vorgehensweise</strong>: Zähler und Nenner heben sich bei \\(x={@{avar}@}\\) gegenseitig auf (unbestimmte Form 0/0). Wir faktorisieren \\((x-{@{avar}@})\\) im Zähler: \\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\).<br>Man vereinfacht mit dem identischen Faktor im Nenner: \\(\\frac{(x-{@{avar}@})({@{qvar}@})}{x-{@{avar}@}}={@{qvar}@}\\).<br>Nun muss noch bei \\(x={@{avar}@}\\) ausgewertet werden: {@{tavar}@}.",
  "lim.fbgen_point_fini":  "Faktorisieren Sie \\((x-{@{avar}@})\\) im Zähler (\\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\)), und vereinfachen Sie anschließend mit dem Nenner: Es bleibt \\({@{qvar}@}\\) übrig. <br>Bei \\(x={@{avar}@}\\) ergibt sich \\(\\lim={@{tavar}@}\\).",
  "lim.fb_wrong_droite":   "<strong>Vorgehensweise</strong>: Man führt die Variablenänderung \\(u=x-{@{avar}@}\\) ein; wenn \\(x\\to{@{avar}@}^+\\) gilt, dann gilt \\(u\\to 0^+\\) (u bleibt positiv).<br>Der Ausdruck lautet nun \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\).<br>Wenn \\(u\\to 0^+\\) ist, gilt \\(\\sqrt{u}\\to 0^+\\), also \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fbgen_droite":      "Setzen wir \\(u=x-{@{avar}@}\\to 0^+\\) an: Der Ausdruck wird zu \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fb_wrong_gauche":   "<strong>Vorgehensweise</strong>: Man setzt \\(u={@{avar}@}-x\\) ; wenn \\(x\\to{@{avar}@}^-\\) gilt, dann gilt \\(u\\to 0^+\\) und \\(x-{@{avar}@}=-u\\).<br>Der Ausdruck lautet nun \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\).<br>Wenn \\(u\\to 0^+\\) ist, geht \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\), also geht der Ausdruck gegen \\(-\\infty\\) hin.",
  "lim.fbgen_gauche":      "Setzen wir \\(u={@{avar}@}-x\\to 0^+\\), wobei \\(x-{@{avar}@}=-u\\) gilt: Der Ausdruck wird zu \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\to-\\infty\\).",

