  "osc.consigne_lbl": "Anweisung:",
  "osc.consigne_periode_frequence": "Messen Sie mithilfe der Schieberegler (Schaltflächen <span style=\"color:#7c3aed;font-weight:bold;\">■ X</span> und <span style=\"color:#b91c1c;font-weight:bold;\">■ Y</span>) die Periode \\(T\\) der Spannung <strong>{@ta{X}_type_text@}</strong> und leiten Sie daraus deren Frequenz \\(f\\) ab.",
