  "sui.fb_wrong_somme_geo":"Falsch. \\(S_n=U_0\\frac{1-q^n}{1-q}={@{ansvar}@}\\).",
  "sui.fbgen_somme_geo":   "\\(S_n = U_0 \\ \frac{1 - q^n}{1 - q} = {@{ansvar}@}\\).",
