  "log.ordre_title":          "Achtet auf die Reihenfolge!",
  "log.ordre_3vars_desc":     "Bei drei Variablen lautet die Reihenfolge P (hohe Gewichtung) → Q → R (niedrige Gewichtung). Sie scheinen die Reihenfolge vertauscht zu haben.",
  "log.ordre_2vars_desc":     "Sie haben die Tabelle beginnend mit P=1, Q=1 (von oben nach unten) ausgefüllt, obwohl man sie beginnend mit P=0, Q=0 (von unten nach oben) ausfüllen muss.",
  "log.table_fallback_desc":  "Überprüfen Sie Schritt für Schritt die Auswertung jedes Operators. Zur Erinnerung:<br>• Die Implikation \\(P \\to Q\\) ist <u>nur</u> dann falsch, wenn P wahr und Q falsch ist.<br>• Das „NICHT“ hat Vorrang.",
