  "log.identifier_fallback_desc": "Um den richtigen Ausdruck zu finden, suchen Sie die Zeilen, in denen das Ergebnis <strong>1</strong> lautet, und leiten Sie daraus den wichtigsten logischen Konnektor ab:<br>• Wenn nur (1,1) 1 ergibt → <em>UND</em><br>• Wenn nur (0,0) 0 ergibt → <em>ODER</em><br>• Wenn nur (1,0) 0 ergibt → <em>IMPLIZIERT</em>",
