  "cpx.fbdetail_warn":          "⚠ Diese Texte werden bei jedem Klick auf „Speichern“ neu generiert. Um einen PRT-Knoten nach dem Speichern zu bearbeiten, ohne erneut diese Felder ausfüllen zu müssen, verwenden Sie die Schaltfläche „🌿 PRT-Baum“ am unteren Rand des Fensters – wenn Sie die Konfiguration anschließend jedoch erneut speichern, wird diese manuelle Bearbeitung durch den hier definierten Text überschrieben.",
