  "calc.scenario_tvi":           "TVI und Einordnung nach Dichotomie",
  "calc.scenario_aire":          "Fläche zwischen zwei Kurven (Polynome)",
  "calc.scenario_tangente_ext":  "Tangente, die durch einen Punkt außerhalb der Kurve verläuft",
