  /* ── Circuits électriques (CIR) ── */
  "cir.title":              "Elektrische Schaltungen (Konstruktionswerkstatt)",
  "cir.teacher_help":       "Erstellen Sie unten die Schaltung, die die Schüler originalgetreu nachbauen sollen: Klicken Sie auf ein Bauteil auf der rechten Seite, um es zu platzieren, und klicken Sie auf zwei Anschlüsse, um ein Kabel zu verlegen. Klicken Sie auf ein Bauteil im Schaltplan, um es auszuwählen (verschieben, drehen, Wert anpassen).",
  "cir.check_values_lbl":   "Auch die korrekten Werte der Bauteile einfordern (nicht nur die Verkabelung)",
  "cir.text_lbl":           "Aufgabe",
  "cir.err_no_model":       "Bauen Sie zunächst in der obigen Werkstatt eine Schaltung auf, bevor Sie diese Frage speichern.",
  "cir.status_components":  "{n} platzierte(s) Bauteil(e), {m} elektrische(r) Knoten.",
  "cir.status_empty":       "Es wurde noch keine Komponente platziert – klicken Sie rechts auf eine Komponente, um zu beginnen.",
  "cir.fbgen_auto_desc":    "Die Korrektur erfolgt automatisch und umfasst drei aufeinanderfolgende Kriterien: die platzierten Bauteile, die Verdrahtung (Topologie) und – sofern aktiviert – die Werte der Bauteile. In diesem Feld kann ein ergänzender Erläuterungskommentar hinzugefügt werden, der zusätzlich zur Korrektur angezeigt wird.",
  "cir.atelier_title":      "Werkstatt elektrische Schaltungen",
  "cir.atelier_instructions": "Klicke auf ein Bauteil rechts, um es zu platzieren. Klicke auf ein Bauteil im Schaltplan, um es <strong>auszuwählen</strong>: Ein graues Quadrat erscheint, ziehe es, um das Bauteil zu verschieben. <strong>⟳</strong> zum Drehen, die Beschriftung (✎), um einen Wert zu ändern. Klicke auf zwei Anschlüsse, um ein Kabel zu ziehen. Ein bereits ausgewählter Schalter schaltet um, wenn erneut darauf geklickt wird.",
  "cir.btn_scissors":       "Schere",
  "cir.btn_undo":           "Punkt rückgängig",
  "cir.btn_reset":          "Alles leeren",
  "cir.feedback_placeholder": "Wähle rechts ein Bauteil, um zu beginnen.",
