  "cir.teacher_atelier_instructions": "Bauen Sie hier die Schaltung, die die Schüler identisch nachbauen müssen. Klicken Sie auf ein Bauteil rechts, um es zu platzieren. Klicken Sie auf ein Bauteil im Schaltplan, um es <strong>auszuwählen</strong>: Ziehen Sie sein graues Quadrat, um es zu verschieben, <strong>⟳</strong> zum Drehen, die Beschriftung (✎), um seinen Wert zu ändern. Klicken Sie auf zwei Anschlüsse, um ein Kabel zu ziehen.",
