  "bn.fb_err_format_desc":   "Die Berechnung ist richtig, aber die Formatierung entspricht nicht der Vorgabe (Leerzeichen, Groß-/Kleinschreibung, Präfix oder führende Null). Lesen Sie den Hinweis zur Schreibweise oben noch einmal.",
  "bn.fb_err_minuscules_desc": "Das Ergebnis sieht gut aus, aber die Buchstaben müssen in <strong>Großbuchstaben</strong> geschrieben sein.",
