  "imm.methode_ecart_desc":     "Man misst den Abstand in Pixeln <strong>zwischen den beiden Punkten</strong> (es handelt sich nicht um eine Position relativ zum Bezugspunkt 1, sondern um einen Abstand): {pxDist} px.<br>Man multipliziert mit dem Maßstab&nbsp;: {pxDist} × {echelleRounded} = <strong>{val} {unit}</strong>.<br>⚠️ Der Wert von Bezugspunkt 1 wird nicht addiert: Ein Abstand zwischen zwei Punkten hat keinen Ursprung.",
  "imm.methode_position_desc":  "Man misst den Abstand in Pixeln zwischen dem <strong>Bezugspunkt 1</strong> und diesem Punkt: {pxDist} px.<br>Man multipliziert mit dem Maßstab: {pxDist} × {echelleRounded} = {rawDist} {unit}.<br>Da der Bezugspunkt 1 nicht unbedingt 0 ist, addiert man seinen Ursprung hinzu&nbsp;: {rawDist} + {r1v} = <strong>{val} {unit}</strong>.",
