  "rx.method_equivalence_vwrong": "Veq ist das Volumen, bei dem die Kurve einen <strong>abrupten Potenzialsprung</strong> (Steigungsbruch) zeigt: dort ist der titrierte Reaktant gerade vollständig verbraucht.",
