  "rx.method_eo2_ewrong":       "Kurz <strong>vor dem Äquivalenzpunkt</strong> ist die titrierte Spezies noch weitgehend vorhanden: das Potenzial bleibt nahe E°₂ (Plateau vor dem Sprung).",
  "rx.method_eo2_label":        "E°₂ = {e2} V (Plateau vor dem Sprung, V ≪ Veq)",
  "rx.method_demi_vwrong":      "Der Halbäquivalenzpunkt entspricht <strong>V = Veq / 2</strong>, also der Hälfte des Volumens, bei dem der Potenzialsprung auftritt.",
  "rx.method_demi_ewrong":      "Am Halbäquivalenzpunkt sind die Konzentrationen der beiden Formen des titrierten Redoxpaars gleich ([Ox₂] = [Red₂]): in der Nernst-Gleichung verschwindet der logarithmische Term, also <strong>E = E°₂</strong>.",
  "rx.method_demi_label":       "Halbäquivalenz: V = Veq/2 = {v} mL, E = E°₂ = {e2} V",
  "rx.method_double_vwrong":    "Der Punkt der doppelten Äquivalenz entspricht <strong>V = 2 × Veq</strong>: der zugegebene Titrantüberschuss entspricht dann der anfänglichen Stoffmenge der titrierten Spezies.",
  "rx.method_double_ewrong":    "In diesem Überschuss sind die Konzentrationen der beiden Formen des Titrant-Redoxpaars gleich ([Ox₁] = [Red₁]): nach Nernst gilt <strong>E = E°₁</strong>.",
