  "opt.tel_type": "Bild in der Brennebene",
  "opt.mic_type": "Reelles Zwischenbild, dann afokales System",
  "opt.info_lentille_convergente": "✏️ Der Schüler zeichnet mindestens zwei der drei besonderen Strahlen von B mithilfe der Werkzeugleiste (Strahl 2 Klicks, Strahl // Achse, paralleler Strahl 3 Klicks) und konstruiert dann den Punkt B' durch Schnitt der austretenden Strahlen. Der Reell-/Virtuell-Status jedes Abschnitts wird automatisch korrigiert.",
  "opt.info_lentille_divergente": "✏️ Wie bei der Sammellinse, aber das Bild ist <strong>immer virtuell</strong>: Die austretenden Strahlen divergieren hinter der Linse und müssen rückwärts (gestrichelt) verlängert werden, um B' zu konstruieren.",
  "opt.info_miroir_plan": "✏️ Der Schüler zeichnet die beiden besonderen Strahlen von B (senkrechter Einfall und ein Strahl, der bei S ankommt), lässt sie am ebenen Spiegel reflektieren und konstruiert dann B' durch Schnitt der verlängerten reflektierten Strahlen. Das Bild ist <strong>immer virtuell und gleich groß</strong> wie das Objekt.",
  "opt.info_miroir_concave": "✏️ Der Schüler zeichnet mindestens zwei der vier besonderen Strahlen von B (// Achse, durch C, durch F, zu S), lässt sie am Spiegel reflektieren und konstruiert dann B' durch Schnitt der reflektierten Strahlen. Je nach Position des Objekts (SA &lt; f oder SA &gt; f) ist das Bild virtuell oder reell — der erwartete Reell-/Virtuell-Status jedes Abschnitts wird automatisch korrigiert.",
  "opt.info_miroir_convexe": "✏️ Wie beim Hohlspiegel, aber Brennpunkt F und Mittelpunkt C sind <strong>virtuell</strong> (hinter dem Spiegel): Das entstehende Bild ist immer virtuell, unabhängig von der Position des Objekts.",
  "opt.info_lunette_galilee": "✏️ Der Schüler konstruiert vier besondere Strahlen: zwei parallele einfallende Strahlen (einer durch die Mitte des Objektivs), die sich in B&#8321; in der gemeinsamen Brennebene schneiden, dann zwei Strahlen von B&#8321; zum Okular, die parallel austreten (afokales System, Bild im Unendlichen). Der Punkt B&#8321; wird mit dem Werkzeug „Schnittpunkt“ konstruiert.",
  "opt.info_telescope_newton": "✏️ Der Schüler konstruiert zwei parallele einfallende Strahlen, die um θ geneigt sind (einer berührt den Scheitel S des Hauptspiegels, der andere ist um h versetzt), sowie ihre entsprechenden reflektierten Strahlen (für den am Scheitel reflektierten Strahl „Spiegeln an Achse“ verwenden), die sich im Bildpunkt B&#8321; in der Brennebene des Spiegels schneiden. Der Punkt B&#8321; wird mit dem Werkzeug „Schnittpunkt“ konstruiert.",
  "opt.info_microscope": "✏️ Der Schüler zeichnet mindestens zwei der drei besonderen Strahlen von B durch das Objektiv L&#8321;, die sich in B&#8321; schneiden (reelles Zwischenbild, konstruiert mit „Schnittpunkt“), dann die beiden Strahlen von B&#8321; durch das Okular L&#8322;, das so platziert ist, dass B&#8321; genau in dessen objektseitiger Brennebene liegt (Einstellung für ein normalsichtiges Auge): Das austretende Bündel verläuft parallel (Endbild im Unendlichen).",
  "opt.head_lentille_convergente": "Optik — Sammellinse",
