  "phy.enonce_mrua_vitesse": "Ein Körper mit gleichmäßig beschleunigter geradliniger Bewegung startet mit einer Anfangsgeschwindigkeit \\(v_0={@{v0}@}\\) m/s und erfährt eine konstante Beschleunigung \\(a={@{a}@}\\) m/s². Berechnen Sie seine Geschwindigkeit \\(v\\) zum Zeitpunkt \\(t={@{t}@}\\) s.",
