  "inc.fb_ecr_unite_ok": "Einheit korrekt.",
  "inc.fb_ecr_unite_wrong": "Einheit falsch: Zerlegen Sie die eingegebene Einheit in SI-Basiseinheiten (kg, m, s, A, K, mol, cd) und vergleichen Sie sie mit der der gemessenen Größe — eine Verwechslung physikalischer Größen oder eine falsche Vereinfachung führt zu diesem Fehler. Eine gültige Einheit wäre zum Beispiel {@{unitvar}@}.",
