  "inc.fb_wrong_ecr": "Falsch. Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_moyenne": "Mittelwert falsch: Berechnen Sie den arithmetischen Mittelwert neu (Summe aller Messwerte geteilt durch ihre Anzahl n). Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_s": "Standardabweichung falsch: Verwenden Sie die Formel der experimentellen Standardabweichung mit n−1 Messwerten im Nenner (Bessel-Korrektur), nicht n. Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_uA": "Unsicherheit Typ A falsch: Sie ergibt sich aus der Standardabweichung s geteilt durch die Quadratwurzel der Anzahl der Messungen n (Unsicherheit des Mittelwerts, nicht einer Einzelmessung). Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_uB_resolution": "Unsicherheit Typ B falsch: Bei einer Auflösungsunsicherheit teilen Sie die Auflösung des Instruments durch √12 (Gleichverteilung über das Ableseintervall). Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_uB_tolerance": "Unsicherheit Typ B falsch: Teilen Sie die vom Hersteller angegebene Toleranz (Halbbereich) durch √3 (Gleichverteilung). Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_uB_calibration": "Unsicherheit Typ B falsch: Teilen Sie die Unsicherheit des Kalibrierzertifikats durch den angegebenen Erweiterungsfaktor k. Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_uB_impose": "Unsicherheit Typ B falsch: Dieser Wert ist eine Vorgabe der Aufgabenstellung und muss unverändert übernommen werden, ohne Berechnung. Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_uc": "Kombinierte Unsicherheit falsch: Kombinieren Sie uA und uB quadratisch (Wurzel aus der Summe der Quadrate), nicht durch einfache Addition. Erwartete Antwort: {@{tavar}@}",
  "inc.fb_wrong_U": "Erweiterte Unsicherheit falsch: Überprüfen Sie U = k×uc und runden Sie danach auf 1 oder 2 signifikante Stellen auf (nie ab). Erwartete Antwort: {@{tavar}@}",
  "inc.fb_ok_moyenne": "Mittelwert korrekt.",
  "inc.fb_ok_s": "Standardabweichung korrekt.",
