  /* ── Cinématique du point (vecteur vitesse, relation de Chasles) ── */
  "type.cinematique":        "Punktkinematik (Geschwindigkeitsvektor, Chasles-Relation)",
  "data.label.cinematique":  "🏃 Punktkinematik",
  "cin.title": "Punktkinematik",
  "cin.info_box": "Chronofotografie eines bewegten Punktes M: Der Schüler zeichnet selbst die Verschiebungsvektoren M_iM_{i+1} und M_{i+1}M_{i+2} im Diagramm, leitet daraus die Beträge der Geschwindigkeitsvektoren vᵢ und vᵢ₊₁ ab und konstruiert dann Δvᵢ = vᵢ₊₁ − vᵢ mithilfe der Chasles-Relation (Klonen, Auswahl, Umkehrung, magnetisches Einrasten).",
  "cin.atelier_title": "Werkstatt zur Digitalisierung der Punkte",
  "cin.atelier_hint": "Klicken Sie jede Position M0, M1, M2… in chronologischer Reihenfolge, auf freiem Hintergrund oder einem importierten Bild. Das Bild dient nur als visuelle Hilfe: Es wird nie gespeichert oder exportiert, nur die angeklickten Punkte und die Kalibrierung.",
  "cin.atelier_upload_btn": "Bild hochladen (Hilfe, nicht gespeichert)…",
  "cin.atelier_remove_img_btn": "Bild entfernen",
  "cin.atelier_tool_points": "Punkte",
  "cin.atelier_tool_calib": "Kalibrierung",
  "cin.calib_dist_lbl": "Reale Entfernung zwischen den 2 Referenzmarken (m)",
  "cin.atelier_point_list_lbl": "Digitalisierte Punkte",
  "cin.hint_points": "Klicken Sie auf den Hintergrund, um den nächsten Punkt zu setzen (M{n}).",
  "cin.hint_calib1": "Klicken Sie auf die 1. Kalibrierungsmarke.",
  "cin.hint_calib2": "Klicken Sie auf die 2. Kalibrierungsmarke.",
  "cin.hint_calib_done": "Kalibrierung gesetzt. Geben Sie unten den tatsächlichen Abstand zwischen den 2 Marken ein.",
  "cin.hint_select": "Klicken Sie auf einen Punkt, um ihn auszuwählen (Löschen über die Liste).",
  "cin.point_list_empty": "Noch kein Punkt. Klicken Sie oben auf den Hintergrund, um M0 zu setzen.",
  "cin.echelle_deduite": "Abgeleiteter Maßstab: {echelle} m/px ({px} px ↔ {m} m).",
  "cin.dt_lbl": "Intervall zwischen 2 Fotos (s)",
  "cin.method_lbl": "Berechnungsmethode der Geschwindigkeit",
  "cin.method_hint": "« Nächster Punkt » (Lehrplan 2019) verwendet MᵢMᵢ₊₁/Δt. « Symmetrische Ableitung » verwendet Mᵢ₋₁Mᵢ₊₁/(2Δt): empfohlen für kreisförmige oder parabolische Bewegungen, wo sie eine korrekte Tangentenrichtung liefert.",
  "cin.method_apres": "Nächster Punkt (MᵢMᵢ₊₁/Δt)",
  "cin.method_symetrique": "Symmetrische Ableitung (Mᵢ₋₁Mᵢ₊₁/2Δt)",
  "cin.iidx_title": "Messpunkt der Geschwindigkeitsvektoren",
  "cin.iidx_hint": "Index i des ersten verwendeten Punktes: Der Schüler zeichnet M_iM_{i+1} (für vᵢ) dann M_{i+1}M_{i+2} (für vᵢ₊₁) im Diagramm. In der Vorschau erscheint eine Fehlermeldung, wenn i außerhalb des Bereichs für die Anzahl der digitalisierten Punkte liegt.",
  "cin.iidx_lbl": "Index i des Startpunkts",
  "cin.fbgen_auto_desc": "Die Korrektur (Betrag vᵢ und Konstruktion von Δvᵢ) wird automatisch erzeugt. Dieses Feld ermöglicht das Hinzufügen eines zusätzlichen pädagogischen Kommentars.",
  "cin.header_title": "Punktkinematik — Verschiebungsvektoren und Chasles-Relation",
  "cin.preview_err_not_enough_points": "Es müssen mindestens 3 Punkte M₀, M₁, M₂… in der Werkstatt digitalisiert werden, um die Vorschau zu erzeugen. Setzen Sie weitere Positionen auf den Hintergrund (frei oder importiertes Bild).",
  "cin.preview_err_bad_calib": "Die Maßstabskalibrierung ist unvollständig oder entartet: Setzen Sie 2 unterschiedliche Kalibrierungspunkte und geben Sie einen streng positiven realen Abstand zwischen ihnen an.",
  "cin.preview_err_bad_index": "Der gewählte Index i ({iIdx}) liegt außerhalb des Bereichs für die Anzahl digitalisierter Punkte: er muss zwischen {iMin} und {iMax} liegen.",
  "cin.preview_step1_label": "Schritt 1 — Messung des Betrags v<sub>i</sub>",
  "cin.preview_step2_label": "Schritt 2 — Konstruktion von Δv<sub>i</sub> (Chasles-Relation)",
  "cin.preview_default_statement": "Automatische Aufgabenstellung: Messung des Betrags des Geschwindigkeitsvektors, dann Konstruktion von Δv<sub>i</sub> mittels der Chasles-Relation.",
  "cin.preview_unavailable_fallback": "Vorschau nicht verfügbar: Digitalisieren Sie mindestens 3 Punkte in der Werkstatt und legen Sie die Kalibrierung fest.",
  "cin.err_not_enough_points": "Es müssen mindestens 3 Punkte M₀, M₁, M₂… in der Werkstatt digitalisiert werden, um die Frage zu erzeugen. Klicken Sie weitere Positionen auf dem Hintergrund (frei oder importiertes Bild).",
  "cin.err_bad_calib": "Die Skalenkalibrierung ist unvollständig oder entartet: setzen Sie 2 unterschiedliche Kalibrierungspunkte und geben Sie eine streng positive reale Entfernung zwischen ihnen an.",
  "cin.err_bad_index": "Der gewählte Index i ({iIdx}) liegt außerhalb des Bereichs für die Anzahl der digitalisierten Punkte: er muss zwischen {iMin} und {iMax} liegen. Passen Sie das Feld « Index i des Startpunkts » in der Werkstatt an{extra}.",
  "cin.err_bad_index_extra": " (die Methode der symmetrischen Ableitung erfordert einen Punkt vor M{iMin})",
  "cin.step1_title": "Schritt 1 — Verschiebungs- und Geschwindigkeitsvektoren",
  "cin.step1_instruction": "Zeichnen Sie im untenstehenden Diagramm den Verschiebungsvektor M<sub>{a1}</sub>M<sub>{b1}</sub> dann M<sub>{a2}</sub>M<sub>{b2}</sub> (dedizierte Schaltflächen), und leiten Sie dann die Beträge der Geschwindigkeitsvektoren v<sub>{i}</sub> und v<sub>{ip1}</sub> in m/s ab (Segmentdauer: {dtEff} s).",
  "cin.step2_title": "Schritt 2 — Konstruktion von Δv<sub>{i}</sub> mithilfe der Chasles-Relation",
  "cin.step2_instruction": "Sobald v<sub>{i}</sub> und v<sub>{ip1}</sub> oben eingegeben wurden, erscheinen die Vektoren v<sub>{i}</sub> (blau, von M<sub>{i}</sub>) und v<sub>{ip1}</sub> (grün, von M<sub>{ip1}</sub>) unten. Klonen Sie sie (dedizierte Schaltflächen), positionieren und orientieren Sie die Klone (automatisches Einrasten beim Annähern an eine vorhandene Spitze), um Δv<sub>{i}</sub> = v<sub>{ip1}</sub> − v<sub>{i}</sub> mithilfe der Chasles-Relation zu konstruieren, und zeichnen Sie dann den Ergebnisvektor (rot) mit der dedizierten Schaltfläche.",
  "cin.preview_placeholder": "📐 Zeichnung der Verschiebungsvektoren + Konstruktion von Δv<sub>i</sub> (Live-Vorschau rechts)",
  "cin.fb_vec_ok": "Vektor M<sub>{a}</sub>M<sub>{b}</sub> korrekt gezeichnet.",
  "cin.fb_vec_ko": "Der gezeichnete Vektor entspricht nicht M<sub>{a}</sub>M<sub>{b}</sub>: überprüfen Sie die 2 angeklickten Punkte (Start dann Ende).",
  "cin.fb_norme_ok": "Betrag von v<sub>{i}</sub> korrekt.",
  "cin.fb_norme_ko": "Betrag von v<sub>{i}</sub> falsch: nehmen Sie die Länge des Vektors M<sub>{a}</sub>M<sub>{b}</sub> (über die Skala) und teilen Sie durch {dtEff} s.",
  "cin.fb_dv_ok": "Korrekte Konstruktion: Ihr Vektor Δv<sub>{i}</sub> entspricht tatsächlich v<sub>{ip1}</sub> − v<sub>{i}</sub>.",
  "cin.fb_dv_ko": "Der gezeichnete Vektor entspricht nicht v<sub>{ip1}</sub> − v<sub>{i}</sub>: wiederholen Sie die Konstruktion mithilfe der Chasles-Relation (klonen Sie v<sub>{i}</sub> und v<sub>{ip1}</sub>, setzen Sie sie Spitze an Spitze, kehren Sie bei Bedarf um).",
  "cin.genfb_step1_title": "Schritt 1 — erwartete Verschiebungsvektoren und Geschwindigkeiten:",
