  "pb.opt_erreur": "Jeder Distraktor muss einer bestimmten Fehlerkategorie entsprechen: 1. Rechenfehler, 2. Begriffsverwechslung, 3. Logikumkehr (Ursache/Wirkung).",
  "pb.opt_piege": "Füge eine 'Falle'-Aussage hinzu, die auf den ersten Blick richtig erscheint, aber wegen einer technischen Feinheit oder einer Ausnahme von der Regel falsch ist.",
  "pb.opt_latex": "Verwende LaTeX-Notation für Formeln. REGELN: benutze $...$ für Inline-Formeln und $$...$$ für Display-Formeln. Inline-Beispiel: \"Die Periode $T = \\frac{1}{f}$ ist der Kehrwert der Frequenz.\" Display-Beispiel: \"$$\\lambda = v \\times T$$\". Schreibe LaTeX-Befehle normal (\\frac, \\times usw.), ohne die Backslashes zu verdoppeln.",
  "pb.role_vf": "Handle als erfahrener Pädagogik-Ingenieur. Deine Aufgabe ist es, eine \"Wahr / Falsch\"-Übung zu entwerfen.",
  "pb.cible_vf": "Ziel: Niveau {niv} in {mat}, Kapitel \"{chap}\".",
