  "pb.vf_ex_incorrect_faux": "Falsch, das ist falsch, weil...",
  "pb.role_qcm": "Handle als erfahrener Ingenieur für Pädagogik und Prüfungswissenschaft. Deine Aufgabe ist es, {type} zu entwerfen.",
  "pb.qcm_type_unique": "eine Übung vom Typ \"Single-Choice-MC\"",
  "pb.qcm_type_multiple": "eine Übung vom Typ \"Multiple-Choice-MC\"",
  "pb.cible_qcm": "Ziel: Niveau {niv} in {mat}, insbesondere in {sous}, Kapitel \"{chap}\".",
  "pb.qcm_consigne1": "Erzeuge genau {xe} Aussagen.",
  "pb.qcm_ra_singular": "Erzeuge {xbr} richtige Antwort (für den Pool \"vrais\") und {distracteurs} plausible Distraktoren (basierend auf typischen Schülerfehlern). Bei jedem Test wird eine einzige richtige Antwort zufällig unter den {xbr} ausgewählt.",
  "pb.qcm_ra_plural": "Erzeuge {xbr} richtige Antworten (für den Pool \"vrais\") und {distracteurs} plausible Distraktoren (basierend auf typischen Schülerfehlern). Bei jedem Test wird eine einzige richtige Antwort zufällig unter den {xbr} ausgewählt.",
  "pb.qcm_cb_consigne2": "Balance: Füge genau {xb} richtige Antworten und {distracteurs} plausible Distraktoren hinzu (basierend auf typischen Schülerfehlern).",
  "pb.qcm_syntaxe": "Alle Aussagen müssen eine ungefähr gleiche Länge und eine identische syntaktische Struktur haben (z. B. immer mit einem Verb oder einem Substantiv beginnen).",
  "pb.qcm_rigueur_feedback": "Feedback-Genauigkeit: Benenne für jeden Distraktor die genaue Verwechslung oder den Fehler, den er offenbart (schreibe niemals nur \"falsch\" oder \"inkorrekt\"), und bekräftige dann das richtige Prinzip, Gesetz oder die Methode. Erkläre bei der richtigen Antwort kurz, warum sie richtig ist.",
  "pb.qcm_contrainte_json_body": "Du darfst KEINEN Text vor oder nach dem JSON-Block erzeugen. Kein Markdown, keine Kommentare. Die Ausgabe muss direkt von einem JSON-Parser verarbeitbar sein.",
